(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-945":{scenario:{company:"Ngoc Ha Environmental Lab",supervisor:{name:"Tạ Minh Nguyệt",role:{vi:"Trưởng phòng Quan trắc hiện trường",en:"Field Monitoring Manager"}},ref_code:"QT-2611",title:{vi:"Mẫu đúng cách. Số đúng thực. Báo cáo đúng luật.",en:"Right sample. True numbers. Lawful report."},brief:{vi:"Bạn hoàn thiện phiếu kết quả quan trắc QT-2611 cho nước thải sau xử lý của một nhà máy dệt nhuộm. Trong ca 8 giờ đã lấy 4 mẫu đơn: COD 118, 186, 154, 92 mg/L tại lưu lượng 40, 80, 60, 20 m3/h. Một chai riêng được lấy để phân tích chì (Pb) tổng. Rà soát phiếu nháp, sửa hóa chất bảo quản mẫu Pb và COD trung bình theo lưu lượng (giới hạn mô phỏng 150 mg/L), rồi lập báo cáo có căn cứ.",en:"You are finalising monitoring result sheet QT-2611 for treated effluent from a textile dyeing plant. Over an 8-hour shift, 4 grab samples were taken: COD 118, 186, 154 and 92 mg/L at flows of 40, 80, 60 and 20 m3/h. A separate bottle was collected for total lead (Pb). Review the draft, correct the Pb sample preservative and the flow-weighted COD (training limit 150 mg/L), then write an evidence-based report."},reference_title:{vi:"Nhật ký hiện trường & bảng bảo quản mẫu đã duyệt · QT-2611",en:"Approved field log & sample preservation table · QT-2611"},fields:[{id:"PB_PRESERV",label:{vi:"Bảo quản mẫu chì (Pb)",en:"Lead (Pb) sample preservation"},initial:"H2SO4 pH<2",expected:"HNO3 pH<2",choices:["H2SO4 pH<2","HNO3 pH<2","NaOH pH>12"],reference:"Bảng bảo quản mẫu theo ISO 5667-3",hint:{vi:"Mẫu kim loại được axit hóa bằng axit nitric; axit sunfuric tạo kết tủa chì sunfat, NaOH chỉ dùng cho mẫu xyanua.",en:"Metal samples are acidified with nitric acid; sulphuric acid precipitates lead sulphate and NaOH is only for cyanide samples."}},{id:"COD_FW",label:{vi:"COD trung bình theo lưu lượng (mg/L)",en:"Flow-weighted COD (mg/L)"},initial:"137.5",expected:"153.4",reference:"Nhật ký lưu lượng & kết quả COD",ref_value:{vi:"COD 118/186/154/92 mg/L tại lưu lượng 40/80/60/20 m3/h",en:"COD 118/186/154/92 mg/L at flows of 40/80/60/20 m3/h"},hint:{vi:"Mẫu lấy lúc lưu lượng lớn phải có trọng số lớn hơn; trung bình cộng che mất đỉnh ô nhiễm.",en:"Samples taken at high flow must carry more weight; a simple average hides the pollution peak."}}],sop32:{vi:"COD đại diện ca = tổng (Ci x Qi) / tổng Qi, lấy 1 chữ số thập phân; không dùng trung bình cộng khi lưu lượng tại các thời điểm lấy mẫu khác nhau.",en:"Shift COD = sum of (Ci x Qi) / sum of Qi, to 1 decimal place; never use a simple average when flows differ between sampling times."},context:{label:"PHIẾU KẾT QUẢ NHÁP / QT-2611",metrics:[{label:{vi:"Số mẫu đơn",en:"Grab samples"},value:"4"},{label:{vi:"Tổng lưu lượng các mẫu",en:"Sum of sample flows"},value:"200 m3/h"},{label:{vi:"Giới hạn COD mô phỏng",en:"Training COD limit"},value:"150 mg/L"}]},crisis:{vi:"Quản lý môi trường của nhà máy gọi: “Bỏ mẫu lúc 11 giờ đi, ghi trung bình cộng 137.5 cho đạt. Tuần sau đoàn kiểm tra xuống, hợp đồng quan trắc năm tới vẫn là của bên em.”",en:"The plant's environmental manager calls: “Drop the 11 o'clock sample and report the simple average of 137.5 so it passes. The inspectors come next week, and next year's monitoring contract stays with you.”"},options:{safe:{vi:"Báo cáo đúng 153.4 mg/L kèm toàn bộ dữ liệu, giữ mẫu lưu và nhật ký, báo trưởng phòng và bộ phận đảm bảo chất lượng; đề xuất nhà máy rà soát hệ thống xử lý và lấy mẫu lặp lại có giám sát.",en:"Report the correct 153.4 mg/L with all data, keep retained samples and logs, inform the manager and QA; advise the plant to review its treatment system and repeat sampling under supervision."},shortcut:{vi:"Loại mẫu lúc 11 giờ và ghi 137.5 mg/L để khách hàng hài lòng, giữ hợp đồng năm sau.",en:"Drop the 11 o'clock sample and report 137.5 mg/L to keep the client and next year's contract."},wait:{vi:"Chưa phát hành phiếu, chờ khách hàng tự quyết định giữ hay bỏ mẫu.",en:"Hold the sheet and wait for the client to decide whether to keep the sample."}},questions:{vi:["Vì sao COD đại diện là 153.4 mg/L chứ không phải 137.5 mg/L? Dữ liệu lưu lượng nào chứng minh?","Nếu mẫu Pb đã bị axit hóa sai bằng H2SO4, bạn xử lý mẫu và báo cáo thế nào để không mất giá trị pháp lý của kết quả?"],en:["Why is the representative COD 153.4 mg/L rather than 137.5 mg/L? Which flow data proves it?","If the Pb sample was wrongly acidified with H2SO4, how do you handle the sample and the report so the result keeps its legal value?"]},hints:{vi:["Đặt phiếu nháp cạnh bảng bảo quản mẫu và đánh dấu hóa chất dùng cho chai Pb.","Nhân từng nồng độ với lưu lượng tương ứng rồi chia tổng lưu lượng theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không được loại mẫu hợp lệ theo yêu cầu khách hàng; mọi áp lực phải báo cáo."],en:["Place the draft next to the preservation table and flag the preservative used for the Pb bottle.","Multiply each concentration by its flow and divide by total flow as set out in SOP 3.2.","Re-read SOP 4.2: valid samples are never dropped at the client's request; any pressure must be reported."]}},learning:{summary:{vi:"Kỹ thuật viên quan trắc môi trường lấy mẫu, đo nhanh tại hiện trường, bảo quản và vận chuyển mẫu nước, khí, đất theo phương pháp chuẩn để phòng thí nghiệm phân tích. Số liệu quan trắc là căn cứ để doanh nghiệp báo cáo cơ quan quản lý và để xã hội giám sát ô nhiễm, nên người làm nghề phải nắm vững kỹ thuật lấy mẫu, chuỗi hành trình mẫu, kiểm soát chất lượng và trung thực tuyệt đối.",en:"An environmental monitoring technician collects samples, takes field measurements and preserves and transports water, air and soil samples using standard methods for laboratory analysis. Monitoring data is the basis for company reports to regulators and public oversight of pollution, so the role demands solid sampling technique, chain of custody, quality control and absolute honesty."},responsibilities:{vi:["Lập kế hoạch lấy mẫu: vị trí, tần suất, thông số, thiết bị và hóa chất bảo quản.","Lấy mẫu nước thải, nước mặt, khí thải, không khí xung quanh đúng phương pháp tiêu chuẩn.","Đo nhanh tại hiện trường: pH, nhiệt độ, oxy hòa tan, độ dẫn điện, lưu lượng.","Bảo quản, niêm phong, vận chuyển mẫu và ghi phiếu chuỗi hành trình mẫu.","Thực hiện mẫu kiểm soát chất lượng hiện trường: mẫu trắng, mẫu lặp và hiệu chuẩn thiết bị."],en:["Plan sampling: locations, frequency, parameters, equipment and preservatives.","Sample wastewater, surface water, stack emissions and ambient air using standard methods.","Take field measurements: pH, temperature, dissolved oxygen, conductivity and flow.","Preserve, seal and transport samples and complete the chain of custody form.","Run field quality control: blanks, duplicates and instrument calibration."]},competencies:[{name:{vi:"Kỹ thuật lấy mẫu",en:"Sampling technique"},desc:{vi:"Chọn vị trí đại diện, lấy mẫu đơn hoặc mẫu tổ hợp theo lưu lượng đúng phương pháp.",en:"Choose representative points and take grab or flow-proportional composite samples correctly."}},{name:{vi:"Bảo quản & vận chuyển mẫu",en:"Sample preservation & transport"},desc:{vi:"Dùng đúng chai, hóa chất bảo quản, nhiệt độ và thời gian lưu mẫu cho từng thông số.",en:"Use the right container, preservative, temperature and holding time for each parameter."}},{name:{vi:"QA/QC hiện trường",en:"Field QA/QC"},desc:{vi:"Hiệu chuẩn thiết bị, lấy mẫu trắng, mẫu lặp và ghi chép đầy đủ để kết quả được chấp nhận.",en:"Calibrate instruments, take blanks and duplicates and keep full records so results are accepted."}},{name:{vi:"An toàn hiện trường",en:"Field safety"},desc:{vi:"Nhận diện nguy cơ tại cửa xả, ống khói, không gian hạn chế và dùng đúng bảo hộ.",en:"Recognise hazards at outfalls, stacks and confined spaces and use the right protective equipment."}},{name:{vi:"Trung thực số liệu",en:"Data integrity"},desc:{vi:"Giữ nguyên dữ liệu thô, không loại mẫu theo ý khách hàng và báo cáo mọi áp lực.",en:"Keep raw data unchanged, never drop samples at the client's wish and report any pressure."}}],knowledge:{vi:["Luật Bảo vệ môi trường số 72/2020/QH14 và Nghị định 08/2022/NĐ-CP hướng dẫn thi hành.","Thông tư 10/2021/TT-BTNMT quy định kỹ thuật quan trắc môi trường và quản lý thông tin, dữ liệu quan trắc.","Bộ tiêu chuẩn ISO 5667 về lấy mẫu, bảo quản và xử lý mẫu nước.","ISO/IEC 17025 về năng lực phòng thí nghiệm và điều kiện chứng nhận hoạt động dịch vụ quan trắc môi trường (VIMCERTS).","Các quy chuẩn kỹ thuật quốc gia hiện hành về nước thải, khí thải và chất lượng môi trường xung quanh."],en:["Law on Environmental Protection No. 72/2020/QH14 and implementing Decree 08/2022/ND-CP.","Circular 10/2021/TT-BTNMT on technical rules for environmental monitoring and monitoring data management.","The ISO 5667 series on sampling, preservation and handling of water samples.","ISO/IEC 17025 on laboratory competence and the certification of environmental monitoring services (VIMCERTS).","Current national technical regulations on wastewater, stack emissions and ambient environmental quality."]},tools:["Máy đo đa chỉ tiêu cầm tay (pH, DO, EC)","Thiết bị lấy mẫu tự động theo lưu lượng","Thiết bị đo lưu lượng kênh hở","Thiết bị lấy mẫu khí thải đẳng động","Thùng bảo quản lạnh & bộ hóa chất bảo quản"],kpis:{vi:["Tỷ lệ mẫu đạt yêu cầu tiếp nhận của phòng thí nghiệm (đúng bảo quản, đúng thời gian lưu).","Tỷ lệ mẫu QC hiện trường đạt (mẫu trắng, mẫu lặp).","Số sai sót trong chuỗi hành trình mẫu (mục tiêu bằng 0).","Tỷ lệ chuyến quan trắc hoàn thành đúng kế hoạch."],en:["Share of samples accepted by the laboratory (correct preservation and holding time).","Pass rate of field QC samples (blanks, duplicates).","Chain of custody errors (target zero).","Share of monitoring trips completed on schedule."]},day:[{time:"06:30",vi:"Hiệu chuẩn máy đo pH, DO; chuẩn bị chai, nhãn và hóa chất bảo quản theo kế hoạch.",en:"Calibrate pH and DO meters; prepare bottles, labels and preservatives per the plan."},{time:"08:00",vi:"Đến nhà máy, họp an toàn, xác nhận vị trí lấy mẫu tại cửa xả cuối cùng.",en:"Arrive at the plant, attend the safety briefing and confirm the final outfall sampling point."},{time:"09:00",vi:"Lấy mẫu đơn theo giờ, đo nhanh tại chỗ và ghi lưu lượng từng thời điểm.",en:"Take hourly grab samples, measure on site and record the flow at each time."},{time:"13:30",vi:"Lấy mẫu khí thải ống khói lò hơi theo phương pháp đẳng động.",en:"Sample boiler stack emissions using the isokinetic method."},{time:"16:00",vi:"Niêm phong mẫu, bàn giao phòng thí nghiệm kèm phiếu chuỗi hành trình mẫu.",en:"Seal samples and hand them to the laboratory with the chain of custody form."}],mistakes:{vi:["Dùng sai hóa chất bảo quản hoặc để mẫu quá thời gian lưu cho phép.","Lấy trung bình cộng các mẫu đơn khi lưu lượng thay đổi mạnh trong ca.","Lấy mẫu ở vị trí không đại diện, ví dụ sau điểm pha loãng hoặc vùng nước tù."],en:["Using the wrong preservative or exceeding the allowed holding time.","Averaging grab samples arithmetically when flow changes sharply during the shift.","Sampling at an unrepresentative point, such as after dilution or in stagnant water."]},career:[{vi:"Kỹ thuật viên lấy mẫu",en:"Sampling technician"},{vi:"Kỹ thuật viên quan trắc chính",en:"Senior monitoring technician"},{vi:"Trưởng nhóm quan trắc hiện trường",en:"Field monitoring team lead"},{vi:"Quản lý kỹ thuật phòng thí nghiệm môi trường",en:"Environmental laboratory technical manager"}],glossary:[{term:"Grab sample",vi:"Mẫu đơn: mẫu lấy tại một thời điểm, phản ánh chất lượng nước ngay lúc lấy.",en:"A single sample taken at one moment, showing quality at that time."},{term:"Composite sample",vi:"Mẫu tổ hợp: trộn nhiều mẫu đơn theo thời gian hoặc theo tỷ lệ lưu lượng.",en:"A mix of several grab samples combined by time or in proportion to flow."},{term:"Chain of custody",vi:"Chuỗi hành trình mẫu: hồ sơ ghi mọi lần chuyển giao mẫu từ lúc lấy đến lúc phân tích.",en:"Record of every handover of a sample from collection to analysis."},{term:"Field blank",vi:"Mẫu trắng hiện trường: nước sạch đi cùng quy trình lấy mẫu để phát hiện nhiễm bẩn.",en:"Clean water taken through the sampling process to detect contamination."},{term:"COD",vi:"Nhu cầu oxy hóa học: lượng oxy cần để oxy hóa chất hữu cơ trong nước, đơn vị mg/L.",en:"Chemical oxygen demand: oxygen needed to oxidise organic matter in water, in mg/L."}],quiz:[{q:{vi:"Mẫu phân tích kim loại nặng trong nước thường được bảo quản bằng cách nào?",en:"How are water samples for heavy metals usually preserved?"},options:{vi:["Thêm NaOH đến pH lớn hơn 12","Axit hóa bằng HNO3 đến pH nhỏ hơn 2","Thêm H2SO4 đến pH nhỏ hơn 2","Không cần bảo quản"],en:["Add NaOH to pH above 12","Acidify with HNO3 to pH below 2","Add H2SO4 to pH below 2","No preservation needed"]},answer:1,explain:{vi:"Axit nitric giữ kim loại ở dạng hòa tan; axit sunfuric có thể tạo kết tủa với chì, bari.",en:"Nitric acid keeps metals dissolved; sulphuric acid can precipitate lead and barium."}},{q:{vi:"Hai mẫu COD 100 mg/L (lưu lượng 30 m3/h) và 200 mg/L (lưu lượng 70 m3/h). COD trung bình theo lưu lượng là bao nhiêu?",en:"Two COD samples: 100 mg/L at 30 m3/h and 200 mg/L at 70 m3/h. What is the flow-weighted COD?"},options:{vi:["150 mg/L","130 mg/L","185 mg/L","170 mg/L"],en:["150 mg/L","130 mg/L","185 mg/L","170 mg/L"]},answer:3,explain:{vi:"COD theo lưu lượng = (100 x 30 + 200 x 70) / (30 + 70) = 17000 / 100 = 170 mg/L.",en:"(100 x 30 + 200 x 70) / (30 + 70) = 17000 / 100 = 170 mg/L."}},{q:{vi:"Khách hàng đề nghị bỏ một mẫu vượt chuẩn khỏi phiếu kết quả. Bạn làm gì?",en:"The client asks you to remove a non-compliant sample from the result sheet. What do you do?"},options:{vi:["Giữ đủ dữ liệu, báo trưởng phòng và lưu bằng chứng","Bỏ mẫu vì khách hàng trả tiền","Lấy mẫu khác lúc nước sạch hơn để thay","Ghi kết quả nhưng không ký"],en:["Keep all data, inform the manager and keep evidence","Drop the sample because the client pays","Replace it with a cleaner sample","Record it but leave it unsigned"]},answer:0,explain:{vi:"Loại bỏ hay thay mẫu hợp lệ là làm sai lệch số liệu quan trắc, vi phạm pháp luật và nguyên tắc ISO/IEC 17025.",en:"Removing or swapping a valid sample falsifies monitoring data, breaking the law and ISO/IEC 17025 principles."}},{q:{vi:"Mẫu trắng hiện trường dùng để làm gì?",en:"What is a field blank used for?"},options:{vi:["Hiệu chuẩn máy đo pH","Tăng số lượng mẫu","Phát hiện nhiễm bẩn trong quá trình lấy, vận chuyển mẫu","Thay thế mẫu lặp"],en:["Calibrating the pH meter","Increasing the sample count","Detecting contamination during sampling and transport","Replacing duplicates"]},answer:2,explain:{vi:"Nếu mẫu trắng có chất cần phân tích, quy trình lấy mẫu hoặc vận chuyển đã bị nhiễm bẩn.",en:"If the blank contains the analyte, the sampling or transport process was contaminated."}}],tools_en:["Portable multiparameter meter (pH, DO, EC)","Flow-proportional automatic sampler","Open channel flow meter","Isokinetic stack sampling equipment","Cooler box & preservative chemical kit"]}}})})(window.KKR);
